queries.movies:
SELECT DISTINCT ?item ?name ?answer ?answerName ?english WHERE {
    hint:Query hint:optimizer "None".
    { SELECT DISTINCT ?item ?name WHERE { ?item wdt:P31 wd:Q11424; wdt:P57 ?answer. ?item rdfs:label ?name. FILTER(LANG(?name)="ar") ?answer rdfs:label ?a. FILTER(LANG(?a)="ar") } LIMIT 200 }
    ?item wdt:P31 wd:Q11424; wdt:P57 ?answer.
    ?answer rdfs:label ?answerName. FILTER(LANG(?answerName)="ar")
    OPTIONAL { ?answer rdfs:label ?english. FILTER(LANG(?english)="en") }
  }

